var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, FW, FH);
figDraw.rect(FW, FH).fill('#ffffff');

/* ---------- helpers ---------- */
function figClip(id, x, y, w, h) {
  var NS = 'http://www.w3.org/2000/svg';
  var svgNode = figDraw.node;
  var defs = svgNode.querySelector('defs');
  if (!defs) { defs = document.createElementNS(NS, 'defs'); svgNode.insertBefore(defs, svgNode.firstChild); }
  var cp = document.createElementNS(NS, 'clipPath');
