  figAttach(g3.polygon(ptsC).fill('#EFA08C').stroke({ color: C_RED, width: 2, linejoin: 'round' }), 'sin');

  var g4 = gRight.group();
  figAngle(g4, vx, vy, 36, x, 54);
  figBraceDown(g4, vx, Bx, 260, 12);
  figText(g4, '1', (vx + Bx) / 2, 292, 19, { halo: 3 });
  figText(g4, 'tan x', Bx + 10, (vy + Math.max(apexY, 40)) / 2, 17,
    { anchor: 'start', style: 'italic', halo: 3 });

  /* nested-area key (numbers make the ordering explicit) */
  var lx = 900, ly = 96;
  var key = [
    ['#FDEDE7', 'tan x/2 = ' + fmt(tn / 2), 'tan'],
    ['#F8C8B8', 'x/2 = ' + fmt(x / 2), 'sector'],
    ['#EFA08C', 'sin x/2 = ' + fmt(sn / 2), 'sin']
  ];
  for (var i = 0; i < 3; i++) {
    var gg = gRight.group().opacity(figDim(key[i][2]));
    gg.rect(15, 15).move(lx, ly + i * 30 - 12).fill(key[i][0]).stroke({ color: C_RED, width: 1.4 });
    figAttach(figText(gg, key[i][1], lx + 23, ly + i * 30, 17, { anchor: 'start', style: 'italic', halo: 3 }), key[i][2]);
  }
}

/* ---------- caption + formula rows ---------- */
function figCaptions() {
  var g = gText;
  var cxs = [514, 759, 1004], keys = ['tan', 'sector', 'sin'];
  var caps = ['Area of triangle', 'Area of sector', 'Area of triangle'];
  var nums = ['tan x', 'x', 'sin x'], hw = [27, 10, 25];
  for (var i = 0; i < 3; i++) {
    var dim = (figState.focus && figState.focus !== keys[i]);
    var gg = g.group().opacity(dim ? 0.3 : 1);
    if (figState.focus === keys[i]) {
      var w = caps[i].length * 8.7 + 16;
      gg.rect(w, 28).move(cxs[i] - w / 2, 298).fill('#FFEFB3').radius(5);
    }
    figAttach(figText(gg, caps[i], cxs[i], 318, 19, { halo: 3 }), keys[i]);
    figText(gg, nums[i], cxs[i], 360, 19, { style: 'italic' });
    gg.line(cxs[i] - hw[i], 368, cxs[i] + hw[i], 368).stroke({ color: C_INK, width: 1.4 });
    figText(gg, '2', cxs[i], 390, 19, {});
  }
  figText(g, '\u2265', 636, 318, 19, {});
  figText(g, '\u2265', 881, 318, 19, {});
  figText(g, '\u2265', 636, 374, 19, {});
  figText(g, '\u2265', 881, 374, 19, {});
}

/* ---------- numeric readout ---------- */
function figReadout() {
  var g = gText, x = figState.x;
  var c = Math.cos(x), sn = Math.sin(x), tn = Math.tan(x);
  g.rect(410, 74).move(10, 368).fill('#FBFBFC').stroke({ color: '#D6DAE0', width: 1 }).radius(5);
  figText(g, 'x = ' + fmt(x, 2) + ' rad  =  ' + fmt(x * 180 / Math.PI, 1) + '\u00b0',
    22, 388, 12.5, { anchor: 'start', family: SANS });
  figText(g, 'tan x/2 = ' + fmt(tn / 2) + '   \u2265   x/2 = ' + fmt(x / 2) + '   \u2265   sin x/2 = ' + fmt(sn / 2),
    22, 406, 12.5, { anchor: 'start', family: SANS });
  figText(g, 'cos x = ' + fmt(c, 4) + '   \u2264   sin x / x = ' + fmt(sn / x, 4) + '   \u2264   1/cos x = ' + fmt(1 / c, 4),
    22, 424, 12.5, { anchor: 'start', family: SANS, fill: '#1a4a75' });
}

/* ---------- render ---------- */
function figRender() {
  gLeft.clear(); gRight.clear(); gText.clear();
  figLeft();
  if (figState.overlay) figOverlay(); else figPanels();
  figCaptions();
  figReadout();
}

/* ---------- controls ---------- */
function update_angleX(v) { figState.x = v; figRender(); }
function toggle_overlayView(on) { figState.overlay = !!on; figRender(); }

var figSteps = [
  { title: 'The unit-circle setup', narration: 'A radius at angle x meets the unit circle at (cos x, sin x), and its extension meets the vertical tangent line at (1, tan x). The base from the origin to (1, 0) has length 1.', state: { angleX: 0.8, overlayView: 'Side by side' } },
  { title: 'Three regions, three areas', narration: 'The same angle generates a big triangle of height tan x, a sector of angle x, and a small triangle of height sin x. Their areas are tan x / 2, x / 2, and sin x / 2.', state: { angleX: 0.8, overlayView: 'Side by side' } },
  { title: 'Nest them to see the ordering', narration: 'Overlaid on one picture, the small triangle sits inside the sector, which sits inside the large triangle \u2014 containment proves tan x / 2 \u2265 x / 2 \u2265 sin x / 2.', state: { angleX: 0.8, overlayView: 'Overlaid' } },
  { title: 'Open the angle wide', narration: 'Push x toward \u03c0/2 and the outer triangle explodes upward (off the top of the frame) while the inner triangle barely grows: the bounds are far apart, so the inequality is loose here.', state: { angleX: 1.45, overlayView: 'Overlaid' } },
  { title: 'Squeeze toward zero', narration: 'As x shrinks, the three nested regions become nearly indistinguishable. Dividing the inequality by sin x / 2 gives cos x \u2264 sin x / x \u2264 1 / cos x, and both bounds tend to 1.', state: { angleX: 0.1, overlayView: 'Overlaid' } },
  { title: 'Read off the limit', narration: 'At a tiny angle the readout shows sin x / x hugging 1, trapped between cos x and 1 / cos x \u2014 the Squeezing Theorem finishes the proof.', state: { angleX: 0.05, overlayView: 'Overlaid' } }
];
var figStepIdx = 0;

function figApplyStep(i) {
  figStepIdx = (i + figSteps.length) % figSteps.length;
  var st = figSteps[figStepIdx];
  var sl = document.getElementById('angleXInput');
  var cb = document.getElementById('overlayViewInput');
  sl.value = st.state.angleX;
  document.getElementById('angleXVal').value = (+st.state.angleX).toFixed(2);
  cb.checked = (st.state.overlayView === 'Overlaid');
  figState.x = +st.state.angleX;
  figState.overlay = cb.checked;
  figState.focus = null;
  hidePopup();
  document.getElementById('stepTitle').textContent = 'Step ' + (figStepIdx + 1) + ': ' + st.title;
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (figStepIdx + 1) + ' / ' + figSteps.length;
  figRender();
}
function nextStep() { figApplyStep(figStepIdx + 1); }
function prevStep() { figApplyStep(figStepIdx - 1); }

/* ---------- boot ---------- */
figStatic();
figApplyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

