<strong id="stepTitle" style="font-size:12px;color:#1a4a75"></strong>
<p id="demoNarration" style="margin:0;font-size:12px;line-height:1.45;color:#222"></p>
<span style="display:flex;gap:6px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11.5px;color:#444"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label>angle <em>x</em> (radians): <output id="angleXVal">0.80</output>
  <input id="angleXInput" type="range" min="0.05" max="1.55" step="0.01" value="0.8"
    oninput="document.getElementById('angleXVal').value=(+this.value).toFixed(2);update_angleX(+this.value)">
</label>
<label><input id="overlayViewInput" type="checkbox" onchange="toggle_overlayView(this.checked)"> Overlaid view (nest the three regions)</label>
<span id="readout" style="display:block;font:11px/1.6 ui-monospace,Consolas,monospace;background:#f4f7fa;border:1px solid #d6dae0;border-radius:4px;padding:6px 8px;color:#16324f"></span>
<span style="font-size:11.5px;color:#555">Click a shape, or its “Area of …” caption, to isolate it and read its area formula.</span>
<button onclick="clearFocus()">Clear highlight</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var FW = 1105, FH = 382;
var C_BLUE = '#2196CE', C_RED = '#F2666B', C_DOT = '#EE4B55', C_DARK = '#8B1E1E',
    C_PINK = '#FBE1D8', C_INK = '#111';
var SERIF = 'Georgia,"Times New Roman",Times,serif';
var OX = 200, OY = 189, RAD = 122;
var BASEY = 189, SUNIT = 123, PXS = [444, 680, 904];
var CAPX = [PXS[0] + SUNIT / 2, PXS[1] + SUNIT / 2, PXS[2] + SUNIT / 2];
var FS = 23, FSL = 22;
var figState = { x: 0.8, overlay: false, focus: null };

var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, FW, FH);
figDraw.rect(FW, FH).fill('#ffffff');

/* ---------- helpers ---------- */
function figClip(id, x, y, w, h) {
  var NS = 'http://www.w3.org/2000/svg';
  var svgNode = figDraw.node;
  var defs = svgNode.querySelector('defs');
  if (!defs) { defs = document.createElementNS(NS, 'defs'); svgNode.insertBefore(defs, svgNode.firstChild); }
  var cp = document.createElementNS(NS, 'clipPath');
  cp.setAttribute('id', id);
  var r = document.createElementNS(NS, 'rect');
  r.setAttribute('x', x); r.setAttribute('y', y);
  r.setAttribute('width', w); r.setAttribute('height', h);
  cp.appendChild(r); defs.appendChild(cp);
  return 'url(#' + id + ')';
}

function figText(g, str, x, y, size, o) {
  o = o || {};
  var t = g.plain(str);
  t.attr({
    x: x, y: y,
    'text-anchor': o.anchor || 'middle',
    'font-family': SERIF,
    'font-size': size,
    'font-style': o.style || 'normal',
    fill: o.fill || C_INK
  });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
  return t;
}

function figHead(g, x, y, a, size, color) {
  var hw = size * 0.42;
  var p = [
    x + ',' + y,
    (x - size * Math.cos(a) + hw * Math.sin(a)) + ',' + (y - size * Math.sin(a) - hw * Math.cos(a)),
    (x - size * Math.cos(a) - hw * Math.sin(a)) + ',' + (y - size * Math.sin(a) + hw * Math.cos(a))
  ].join(' ');
  g.polygon(p).fill(color).stroke('none');
}

function figArrow(g, x1, y1, x2, y2, color, w, size) {
  g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round' });
  figHead(g, x2, y2, Math.atan2(y2 - y1, x2 - x1), size, color);
}

function figArcPath(cx, cy, r, ang) {
  return 'M' + (cx + r) + ',' + cy + ' A' + r + ',' + r + ' 0 0 0 ' +
    (cx + r * Math.cos(ang)) + ',' + (cy - r * Math.sin(ang));
}

function figAngle(g, cx, cy, r, ang, lr, fs) {
  var x1 = cx + r * Math.cos(ang), y1 = cy - r * Math.sin(ang);
  g.path(figArcPath(cx, cy, r, ang)).fill('none').stroke({ color: '#000', width: 1.3 });
  figHead(g, x1, y1, Math.atan2(-Math.cos(ang), -Math.sin(ang)), 7, '#000');
  var la = Math.max(ang * 0.5, 0.38);
  figText(g, 'x', cx + lr * Math.cos(la), cy - lr * Math.sin(la) - 4, fs || FSL, { style: 'italic', halo: 3 });
}

function figBraceDown(g, x1, x2, y, h) {
  var xm = (x1 + x2) / 2;
  var d = 'M' + x1 + ',' + y +
    ' C' + x1 + ',' + (y + h * 0.75) + ' ' + (xm - h * 0.15) + ',' + (y + h * 0.15) + ' ' + xm + ',' + (y + h) +
    ' C' + (xm + h * 0.15) + ',' + (y + h * 0.15) + ' ' + x2 + ',' + (y + h * 0.75) + ' ' + x2 + ',' + y;
  g.path(d).fill('none').stroke({ color: '#000', width: 1.4, linecap: 'round' });
}

function figBraceRight(g, x, y1, y2, w) {
  var ym = (y1 + y2) / 2;
  var d = 'M' + x + ',' + y1 +
    ' C' + (x + w * 0.75) + ',' + y1 + ' ' + (x + w * 0.15) + ',' + (ym + w * 0.15) + ' ' + (x + w) + ',' + ym +
    ' C' + (x + w * 0.15) + ',' + (ym - w * 0.15) + ' ' + (x + w * 0.75) + ',' + y2 + ' ' + x + ',' + y2;
  g.path(d).fill('none').stroke({ color: '#000', width: 1.4, linecap: 'round' });
}

function fmt(v, n) { return v.toFixed(n === undefined ? 3 : n); }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

/* ---------- region semantics ---------- */
function figTip(key) {
  var x = figState.x;
  if (key === 'tan') return 'Large right triangle: legs 1 and tan x  \u2192  area = tan x / 2 = ' + fmt(Math.tan(x) / 2);
  if (key === 'sector') return 'Circular sector of angle x in the unit circle  \u2192  area = x / 2 = ' + fmt(x / 2);
  return 'Small right triangle: base 1, height sin x  \u2192  area = sin x / 2 = ' + fmt(Math.sin(x) / 2);
}
function figPopupText(key) {
  if (key === 'tan') return ['Area of the large triangle',
    'Its legs are the base 1 and the tangent segment of length tan x, so its area is tan x / 2. This triangle completely contains the sector, which is why tan x / 2 \u2265 x / 2.'];
  if (key === 'sector') return ['Area of the circular sector',
    'A sector of angle x in a unit circle covers the fraction x/(2\u03c0) of a disc of area \u03c0, so its area is x / 2. It contains the small triangle and is contained by the large triangle.'];
  return ['Area of the small triangle',
    'Its base is 1 and its height is sin x, so the area is sin x / 2. It sits inside the sector, so x / 2 \u2265 sin x / 2. Dividing the whole chain by sin x / 2 gives 1/cos x \u2265 x / sin x \u2265 1.'];
}
function figAttach(el, key) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(figTip(key), e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { figSetFocus(key); });
  return el;
}
function figSetFocus(k) {
  if (figState.focus === k) { figState.focus = null; hidePopup(); }
  else { figState.focus = k; var p = figPopupText(k); showPopup(p[0], p[1]); }
  figRender();
}
function clearFocus() { figState.focus = null; hidePopup(); figRender(); }
function figDim(key) { return (figState.focus && figState.focus !== key) ? 0.16 : 1; }

/* ---------- layers ---------- */
var gStatic = figDraw.group();
var gLeft = figDraw.group().attr('clip-path', figClip('figClipL', 0, 0, 430, 375));
var gRight = figDraw.group().attr('clip-path', figClip('figClipR', 430, 0, 675, 232));
var gText = figDraw.group();

function figStatic() {
  figArrow(gStatic, 18, OY, 410, OY, '#000', 1.6, 10);
  figArrow(gStatic, OX, 365, OX, 6, '#000', 1.6, 10);
  var ci = gStatic.circle(2 * RAD).center(OX, OY).fill('none').stroke({ color: C_BLUE, width: 4.2 });
  ci.css('cursor', 'pointer');
  ci.on('mousemove', function (e) { showTooltip('Unit circle \u2014 every point is at distance 1 from the origin', e); })
    .on('mouseleave', function () { hideTooltip(); });
}

/* ---------- left construction panel ---------- */
function figLeft() {
  var g = gLeft, x = figState.x;
  var c = Math.cos(x), sn = Math.sin(x), tn = Math.tan(x);
  var bx = OX + RAD, by = OY;
  var Ty = OY - RAD * tn;
  var Px = OX + RAD * c, Py = OY - RAD * sn;

  g.line(OX, OY, bx, Ty).stroke({ color: C_RED, width: 2.2 });
  g.line(bx, by, bx, Ty).stroke({ color: C_RED, width: 2, dasharray: '7,5' });
  g.line(Px, Py, bx, by).stroke({ color: C_RED, width: 2, dasharray: '7,5' });
  g.line(OX, OY, bx, by).stroke({ color: C_DARK, width: 3.6 });

  figAngle(g, OX, OY, 26, x, 46, FSL);
  figBraceDown(g, OX, bx, 200, 13);
  figText(g, '1', (OX + bx) / 2, 234, FS, { halo: 3 });

  function dot(dx, dy, tip) {
    var d = g.circle(12).center(dx, dy).fill(C_DOT).stroke({ color: '#fff', width: 1 });
    d.css('cursor', 'pointer');
    d.on('mousemove', function (e) { showTooltip(tip, e); }).on('mouseleave', function () { hideTooltip(); });
  }
  dot(bx, by, '(1, 0) \u2014 the base has length 1');
  dot(Px, Py, '(cos x, sin x) = ( ' + fmt(c) + ' , ' + fmt(sn) + ' ) on the unit circle');
  if (Ty > 14) dot(bx, Ty, '(1, tan x) \u2014 where the radius, extended, meets the tangent line x = 1');

  /* --- callouts: kept well apart from one another --- */
  var tanY = clamp(Ty - 10, 24, 96);
  figText(g, '(1, tan x)', bx + 14, tanY, FSL, { anchor: 'start', style: 'italic', halo: 3.5 });

  var labX = 356, labY = clamp(Py + 26, 122, 150);
  figText(g, '(cos x, sin x)', labX, labY, FSL, { anchor: 'start', style: 'italic', halo: 3.5 });
  var tx = labX - 8, ty = labY - 6;
  var dx = Px - tx, dy = Py - ty, L = Math.sqrt(dx * dx + dy * dy) || 1, off = 13;
  figArrow(g, tx, ty, Px - dx / L * off, Py - dy / L * off, '#000', 1.3, 8);

  var zeroY = (RAD * sn < 46) ? 210 : 182;
  figText(g, '(1, 0)', bx + 14, zeroY, FSL, { anchor: 'start', style: 'italic', halo: 3.5 });
}

/* ---------- three shapes, side by side ---------- */
function figPanels() {
  var x = figState.x, c = Math.cos(x), sn = Math.sin(x), tn = Math.tan(x);
  var s = SUNIT, vy = BASEY;

  /* A : large triangle */
  var vx = PXS[0], apexY = vy - s * tn;
  var g1 = gRight.group().opacity(figDim('tan'));
  var ptsA = vx + ',' + vy + ' ' + (vx + s) + ',' + vy + ' ' + (vx + s) + ',' + apexY;
  if (figState.focus === 'tan') g1.polygon(ptsA).fill('none').stroke({ color: '#FFB000', width: 10, opacity: 0.5, linejoin: 'round' });
  figAttach(g1.polygon(ptsA).fill(C_PINK).stroke({ color: C_RED, width: 2.2, linejoin: 'round' }), 'tan');
  g1.path(figArcPath(vx, vy, s, x)).fill('none').stroke({ color: C_BLUE, width: 3.2, dasharray: '10,8' });
  figAngle(g1, vx, vy, 23, x, 40, FSL);
  figText(g1, 'tan x', vx + s + 10, (vy + Math.max(apexY, 26)) / 2, FSL, { anchor: 'start', style: 'italic', halo: 3.5 });
  figText(g1, '1', vx + s / 2, vy + 27, FS, { halo: 3 });

  /* B : sector */
  vx = PXS[1];
  var g2 = gRight.group().opacity(figDim('sector'));
  var Bx = vx + s, Pxx = vx + s * c, Pyy = vy - s * sn;
  var sectorPath = 'M' + vx + ',' + vy + ' L' + Bx + ',' + vy +
    ' A' + s + ',' + s + ' 0 0 0 ' + Pxx + ',' + Pyy + ' Z';
  if (figState.focus === 'sector') g2.path(sectorPath).fill('none').stroke({ color: '#FFB000', width: 10, opacity: 0.5, linejoin: 'round' });
  figAttach(g2.path(sectorPath).fill(C_PINK).stroke('none'), 'sector');
  g2.line(vx, vy, Bx, vy).stroke({ color: C_RED, width: 2.2 });
  g2.line(vx, vy, Pxx, Pyy).stroke({ color: C_RED, width: 2.2 });
  g2.path(figArcPath(vx, vy, s, x)).fill('none').stroke({ color: C_BLUE, width: 3.6 });
  figAngle(g2, vx, vy, 23, x, 40, FSL);
  figText(g2, '1', vx + s / 2, vy + 27, FS, { halo: 3 });

  /* C : small triangle */
  vx = PXS[2];
  var g3 = gRight.group().opacity(figDim('sin'));
  Bx = vx + s; Pxx = vx + s * c; Pyy = vy - s * sn;
  var ptsC = vx + ',' + vy + ' ' + Bx + ',' + vy + ' ' + Pxx + ',' + Pyy;
  if (figState.focus === 'sin') g3.polygon(ptsC).fill('none').stroke({ color: '#FFB000', width: 10, opacity: 0.5, linejoin: 'round' });
  figAttach(g3.polygon(ptsC).fill(C_PINK).stroke({ color: C_RED, width: 2.2, linejoin: 'round' }), 'sin');
  g3.path(figArcPath(vx, vy, s, x)).fill('none').stroke({ color: C_BLUE, width: 3.2, dasharray: '10,8' });
  g3.line(Pxx, Pyy, Pxx, vy).stroke({ color: C_RED, width: 1.1, dasharray: '4,4' });
  figAngle(g3, vx, vy, 23, x, 40, FSL);
  figText(g3, '1', vx + s / 2, vy + 27, FS, { halo: 3 });
  g3.line(Pxx, Pyy, Bx + 8, Pyy).stroke({ color: '#000', width: 0.9 });
  figBraceRight(g3, Bx + 10, vy, Pyy, 10);
  figText(g3, 'sin x', Bx + 26, (vy + Pyy) / 2 + 7, FSL, { anchor: 'start', style: 'italic', halo: 3.5 });
}

/* ---------- overlaid (nested) view ---------- */
function figOverlay() {
  var x = figState.x, c = Math.cos(x), sn = Math.sin(x), tn = Math.tan(x);
  var vx = 590, vy = BASEY, s = 200;
  var apexY = vy - s * tn;
  var Bx = vx + s, Pxx = vx + s * c, Pyy = vy - s * sn;

  var g1 = gRight.group().opacity(figDim('tan'));
  var ptsA = vx + ',' + vy + ' ' + Bx + ',' + vy + ' ' + Bx + ',' + apexY;
  if (figState.focus === 'tan') g1.polygon(ptsA).fill('none').stroke({ color: '#FFB000', width: 11, opacity: 0.5, linejoin: 'round' });
  figAttach(g1.polygon(ptsA).fill('#FDEDE7').stroke({ color: C_RED, width: 2.2, linejoin: 'round' }), 'tan');

  var g2 = gRight.group().opacity(figDim('sector'));
  var sectorPath = 'M' + vx + ',' + vy + ' L' + Bx + ',' + vy +
    ' A' + s + ',' + s + ' 0 0 0 ' + Pxx + ',' + Pyy + ' Z';
  if (figState.focus === 'sector') g2.path(sectorPath).fill('none').stroke({ color: '#FFB000', width: 11, opacity: 0.5, linejoin: 'round' });
  figAttach(g2.path(sectorPath).fill('#F8C8B8').stroke('none'), 'sector');
  g2.path(figArcPath(vx, vy, s, x)).fill('none').stroke({ color: C_BLUE, width: 3.6 });
  g2.line(vx, vy, Pxx, Pyy).stroke({ color: C_RED, width: 1.8 });

  var g3 = gRight.group().opacity(figDim('sin'));
  var ptsC = vx + ',' + vy + ' ' + Bx + ',' + vy + ' ' + Pxx + ',' + Pyy;
  if (figState.focus === 'sin') g3.polygon(ptsC).fill('none').stroke({ color: '#FFB000', width: 11, opacity: 0.5, linejoin: 'round' });
  figAttach(g3.polygon(ptsC).fill('#EFA08C').stroke({ color: C_RED, width: 2.2, linejoin: 'round' }), 'sin');

  var g4 = gRight.group();
  figAngle(g4, vx, vy, 32, x, 50, FSL);
  figBraceDown(g4, vx, Bx, 199, 13);
  figText(g4, '1', (vx + Bx) / 2, 226, FS, { halo: 3 });
  figText(g4, 'tan x', Bx + 10, (vy + Math.max(apexY, 24)) / 2, FSL,
    { anchor: 'start', style: 'italic', halo: 3.5 });

  /* nested-area key */
  var lx = 872, ly = 48;
  var key = [
    ['#FDEDE7', 'tan x/2 = ' + fmt(tn / 2), 'tan'],
    ['#F8C8B8', 'x/2 = ' + fmt(x / 2), 'sector'],
    ['#EFA08C', 'sin x/2 = ' + fmt(sn / 2), 'sin']
  ];
  for (var i = 0; i < 3; i++) {
    var gg = gRight.group().opacity(figDim(key[i][2]));
    gg.rect(16, 16).move(lx, ly + i * 32 - 13).fill(key[i][0]).stroke({ color: C_RED, width: 1.5 });
    figAttach(figText(gg, key[i][1], lx + 24, ly + i * 32, 19, { anchor: 'start', style: 'italic', halo: 3.5 }), key[i][2]);
  }
}

/* ---------- caption + formula rows ---------- */
function figCaptions() {
  var g = gText;
  var keys = ['tan', 'sector', 'sin'];
  var caps = ['Area of triangle', 'Area of sector', 'Area of triangle'];
  var nums = ['tan x', 'x', 'sin x'], hw = [33, 10, 31];
  for (var i = 0; i < 3; i++) {
    var dim = (figState.focus && figState.focus !== keys[i]);
    var gg = g.group().opacity(dim ? 0.28 : 1);
    if (figState.focus === keys[i]) {
      var w = caps[i].length * 10.2 + 18;
      gg.rect(w, 32).move(CAPX[i] - w / 2, 221).fill('#FFEFB3').radius(6);
    }
    figAttach(figText(gg, caps[i], CAPX[i], 245, FS, { halo: 3 }), keys[i]);
    figText(gg, nums[i], CAPX[i], 280, FS, { style: 'italic' });
    gg.line(CAPX[i] - hw[i], 289, CAPX[i] + hw[i], 289).stroke({ color: C_INK, width: 1.6 });
    figText(gg, '2', CAPX[i], 311, FS, {});
  }
  var gx = [(CAPX[0] + CAPX[1]) / 2, (CAPX[1] + CAPX[2]) / 2];
  figText(g, '\u2265', gx[0], 245, FS, {});
  figText(g, '\u2265', gx[1], 245, FS, {});
  figText(g, '\u2265', gx[0], 293, FS, {});
  figText(g, '\u2265', gx[1], 293, FS, {});
}

/* ---------- numeric readout (HTML panel, not the drawing) ---------- */
function figReadout() {
  var el = document.getElementById('readout');
  if (!el) return;
  var x = figState.x, c = Math.cos(x), sn = Math.sin(x), tn = Math.tan(x);
  el.innerHTML =
    'x = ' + fmt(x, 2) + ' rad = ' + fmt(x * 180 / Math.PI, 1) + '\u00b0<br>' +
    'tan x/2 = ' + fmt(tn / 2) + ' \u2265 x/2 = ' + fmt(x / 2) + '<br>' +
    '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u2265 sin x/2 = ' + fmt(sn / 2) + '<br>' +
    '<b>cos x = ' + fmt(c, 4) + '<br>&nbsp;&nbsp;\u2264 sin x / x = ' + fmt(sn / x, 4) +
    '<br>&nbsp;&nbsp;\u2264 1/cos x = ' + fmt(1 / c, 4) + '</b>';
}

/* ---------- render ---------- */
function figRender() {
  gLeft.clear(); gRight.clear(); gText.clear();
  figLeft();
  if (figState.overlay) figOverlay(); else figPanels();
  figCaptions();
  figReadout();
}

/* ---------- controls ---------- */
function update_angleX(v) { figState.x = v; figRender(); }
function toggle_overlayView(on) { figState.overlay = !!on; figRender(); }

var figSteps = [
  { title: 'The unit-circle setup', narration: 'A radius at angle x meets the unit circle at (cos x, sin x), and its extension meets the vertical tangent line at (1, tan x). The base from the origin to (1, 0) has length 1.', state: { angleX: 0.8, overlayView: 'Side by side' } },
  { title: 'Three regions, three areas', narration: 'The same angle generates a big triangle of height tan x, a sector of angle x, and a small triangle of height sin x. Their areas are tan x / 2, x / 2 and sin x / 2.', state: { angleX: 0.8, overlayView: 'Side by side' } },
  { title: 'Nest them to see the ordering', narration: 'Overlaid on one picture, the small triangle sits inside the sector, which sits inside the large triangle \u2014 containment proves tan x / 2 \u2265 x / 2 \u2265 sin x / 2.', state: { angleX: 0.8, overlayView: 'Overlaid' } },
  { title: 'Open the angle wide', narration: 'Push x toward \u03c0/2 and the outer triangle explodes upward (off the top of the frame) while the inner triangle barely grows: the bounds are far apart, so the inequality is loose here.', state: { angleX: 1.45, overlayView: 'Overlaid' } },
  { title: 'Squeeze toward zero', narration: 'As x shrinks, the three nested regions become nearly indistinguishable. Dividing the inequality by sin x / 2 gives cos x \u2264 sin x / x \u2264 1 / cos x, and both bounds tend to 1.', state: { angleX: 0.1, overlayView: 'Overlaid' } },
  { title: 'Read off the limit', narration: 'At a tiny angle the readout above shows sin x / x hugging 1, trapped between cos x and 1 / cos x \u2014 the Squeezing Theorem finishes the proof.', state: { angleX: 0.05, overlayView: 'Overlaid' } }
];
var figStepIdx = 0;

function figApplyStep(i) {
  figStepIdx = (i + figSteps.length) % figSteps.length;
  var st = figSteps[figStepIdx];
  var sl = document.getElementById('angleXInput');
  var cb = document.getElementById('overlayViewInput');
  sl.value = st.state.angleX;
  document.getElementById('angleXVal').value = (+st.state.angleX).toFixed(2);
  cb.checked = (st.state.overlayView === 'Overlaid');
  figState.x = +st.state.angleX;
  figState.overlay = cb.checked;
  figState.focus = null;
  hidePopup();
  document.getElementById('stepTitle').textContent = 'Step ' + (figStepIdx + 1) + ': ' + st.title;
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (figStepIdx + 1) + ' / ' + figSteps.length;
  figRender();
}
function nextStep() { figApplyStep(figStepIdx + 1); }
function prevStep() { figApplyStep(figStepIdx - 1); }

/* ---------- boot ---------- */
figStatic();
figApplyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

