var FW = 1070, FH = 410;
var C_BLUE = '#2196CE', C_RED = '#F2666B', C_DOT = '#EE4B55', C_DARK = '#8B1E1E',
    C_PINK = '#FBE1D8', C_INK = '#111';
var SERIF = 'Georgia,"Times New Roman",Times,serif';
/* left construction panel */
var OX = 138, OY = 180, RAD = 95;
/* right shape row */
var BY = 180, SU = 100, CX = [480, 705, 915];
var GX = [(CX[0] + CX[1]) / 2, (CX[1] + CX[2]) / 2];
var FS = 30, FSL = 27;

var figState = { x: 0.8, overlay: false, focus: null, showReadout: false };

var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, FW, FH);
figDraw.rect(FW, FH).fill('#ffffff');

/* ---------------- helpers ---------------- */
function figText(g, str, x, y, size, o) {
  o = o || {};
  var t = g.plain(str);
  t.attr({
    x: x, y: y,
    'text-anchor': o.anchor || 'middle',
    'font-family': SERIF,
    'font-size': size,
    'font-style': o.style || 'normal',
    fill: o.fill || C_INK
  });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
  return t;
}

function figHead(g, x, y, a, size, color) {
  var hw = size * 0.42;
  var p = [
    x + ',' + y,
    (x - size * Math.cos(a) + hw * Math.sin(a)) + ',' + (y - size * Math.sin(a) - hw * Math.cos(a)),
    (x - size * Math.cos(a) - hw * Math.sin(a)) + ',' + (y - size * Math.sin(a) + hw * Math.cos(a))
  ].join(' ');
  g.polygon(p).fill(color).stroke('none');
}

function figArrow(g, x1, y1, x2, y2, color, w, size) {
  g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round' });
  figHead(g, x2, y2, Math.atan2(y2 - y1, x2 - x1), size, color);
}

function figArcPath(cx, cy, r, ang) {
  return 'M' + (cx + r) + ',' + cy + ' A' + r + ',' + r + ' 0 0 0 ' +
    (cx + r * Math.cos(ang)) + ',' + (cy - r * Math.sin(ang));
}

function figAngle(g, cx, cy, r, ang, lr, fs) {
  var x1 = cx + r * Math.cos(ang), y1 = cy - r * Math.sin(ang);
  g.path(figArcPath(cx, cy, r, ang)).fill('none').stroke({ color: '#000', width: 1.3 });
  figHead(g, x1, y1, Math.atan2(-Math.cos(ang), -Math.sin(ang)), 7, '#000');
  var la = Math.max(ang * 0.5, 0.40);
  figText(g, 'x', cx + lr * Math.cos(la), cy - lr * Math.sin(la) - 3, fs || FSL,
    { style: 'italic', halo: 3.5 });
}

function figBraceDown(g, x1, x2, y, h) {
  var xm = (x1 + x2) / 2;
  var d = 'M' + x1 + ',' + y +
    ' C' + x1 + ',' + (y + h * 0.75) + ' ' + (xm - h * 0.15) + ',' + (y + h * 0.15) + ' ' + xm + ',' + (y + h) +
    ' C' + (xm + h * 0.15) + ',' + (y + h * 0.15) + ' ' + x2 + ',' + (y + h * 0.75) + ' ' + x2 + ',' + y;
  g.path(d).fill('none').stroke({ color: '#000', width: 1.5, linecap: 'round' });
}

function figBraceRight(g, x, y1, y2, w) {
  var ym = (y1 + y2) / 2;
  var d = 'M' + x + ',' + y1 +
    ' C' + (x + w * 0.75) + ',' + y1 + ' ' + (x + w * 0.15) + ',' + (ym + w * 0.15) + ' ' + (x + w) + ',' + ym +
    ' C' + (x + w * 0.15) + ',' + (ym - w * 0.15) + ' ' + (x + w * 0.75) + ',' + y2 + ' ' + x + ',' + y2;
  g.path(d).fill('none').stroke({ color: '#000', width: 1.5, linecap: 'round' });
}

function fmt(v, n) { return v.toFixed(n === undefined ? 3 : n); }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

/* ---------------- region semantics ---------------- */
function figTip(key) {
  var x = figState.x;
  if (key === 'tan') return 'Large right triangle: legs 1 and tan x  \u2192  area = tan x / 2 = ' + fmt(Math.tan(x) / 2);
  if (key === 'sector') return 'Circular sector of angle x in the unit circle  \u2192  area = x / 2 = ' + fmt(x / 2);
  return 'Small right triangle: base 1, height sin x  \u2192  area = sin x / 2 = ' + fmt(Math.sin(x) / 2);
}
function figPopupText(key) {
  if (key === 'tan') return ['Area of the large triangle',
    'Its legs are the base 1 and the tangent segment of length tan x, so its area is tan x / 2. This triangle completely contains the sector, which is why tan x / 2 \u2265 x / 2.'];
  if (key === 'sector') return ['Area of the circular sector',
    'A sector of angle x in a unit circle covers the fraction x/(2\u03c0) of a disc of area \u03c0, so its area is x / 2. It contains the small triangle and is contained by the large triangle.'];
  return ['Area of the small triangle',
    'Its base is 1 and its height is sin x, so the area is sin x / 2. It sits inside the sector, so x / 2 \u2265 sin x / 2. Dividing the whole chain by sin x / 2 gives 1/cos x \u2265 x / sin x \u2265 1.'];
}
function figAttach(el, key) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(figTip(key), e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { figSetFocus(key); });
  return el;
}
function figSetFocus(k) {
  if (figState.focus === k) { figState.focus = null; hidePopup(); }
  else { figState.focus = k; var p = figPopupText(k); showPopup(p[0], p[1]); }
  figRender();
}
function clearFocus() { figState.focus = null; hidePopup(); figRender(); }
function figDim(key) { return (figState.focus && figState.focus !== key) ? 0.16 : 1; }

/* ---------------- layers ---------------- */
var gStatic = figDraw.group();
var gLeft = figDraw.group();
var gRight = figDraw.group();
var gText = figDraw.group();

function figStatic() {
  figArrow(gStatic, 10, OY, 332, OY, '#000', 1.7, 11);
  figArrow(gStatic, OX, 312, OX, 14, '#000', 1.7, 11);
  var ci = gStatic.circle(2 * RAD).center(OX, OY).fill('none').stroke({ color: C_BLUE, width: 4.4 });
  ci.css('cursor', 'pointer');
  ci.on('mousemove', function (e) { showTooltip('Unit circle \u2014 every point is at distance 1 from the origin', e); })
    .on('mouseleave', function () { hideTooltip(); });
}

/* ---------------- left construction panel ---------------- */
function figLeft() {
  var g = gLeft, x = figState.x;
  var c = Math.cos(x), sn = Math.sin(x), tn = Math.tan(x);
  var Bx = OX + RAD, By = OY;
  var Ty = OY - RAD * tn;
  var Px = OX + RAD * c, Py = OY - RAD * sn;

  g.line(OX, OY, Bx, Ty).stroke({ color: C_RED, width: 2.4 });
  g.line(Bx, By, Bx, Ty).stroke({ color: C_RED, width: 2.2, dasharray: '7,5' });
  g.line(Px, Py, Bx, By).stroke({ color: C_RED, width: 2.2, dasharray: '7,5' });
  g.line(OX, OY, Bx, By).stroke({ color: C_DARK, width: 3.8 });

  figAngle(g, OX, OY, 24, x, 42, FSL);
  figBraceDown(g, OX, Bx, 190, 13);
  figText(g, '1', (OX + Bx) / 2, 226, FS, { halo: 3 });

  function dot(dx, dy, tip) {
    var d = g.circle(11).center(dx, dy).fill(C_DOT).stroke({ color: '#fff', width: 1 });
    d.css('cursor', 'pointer');
    d.on('mousemove', function (e) { showTooltip(tip, e); }).on('mouseleave', function () { hideTooltip(); });
  }

  /* ---- labels: fixed, generously separated slots, all inside x < 400 ---- */
  var tanY = clamp(Ty - 14, 36, 96);
  figText(g, '(1, tan x)', 246, tanY, FSL, { anchor: 'start', style: 'italic', halo: 4 });
  if (Ty - tanY > 26 && Ty < 300) {
    g.line(250, tanY + 7, Bx + 7, Ty - 4).stroke({ color: '#444', width: 1 });
  }

  var cosY = 142;
  var tCos = figText(g, '(cos x, sin x)', 384, cosY, FSL,
