/* ---------------- caption + formula rows ---------------- */
function figCaptions() {
  var g = gText;
  var keys = ['tan', 'sector', 'sin'];
  var word2 = ['triangle', 'sector', 'triangle'];
  var nums = ['tan x', 'x', 'sin x'];
  for (var i = 0; i < 3; i++) {
    var dim = (figState.focus && figState.focus !== keys[i]);
