    var t1 = figText(gg, 'Area of', CX[i], 270, FS, {});
    var t2 = figText(gg, word2[i], CX[i], 302, FS, {});
    if (figState.focus === keys[i]) {
      var bw = Math.max(t1.bbox().width, t2.bbox().width) + 24;
      gg.rect(bw, 56).move(CX[i] - bw / 2, 250).fill('#FFEFB3').radius(7).back();
    }
    figAttach(t1, keys[i]); figAttach(t2, keys[i]);

    var tn2 = figText(gg, nums[i], CX[i], 352, FS, { style: 'italic' });
    var hw = tn2.bbox().width / 2 + 7;
    gg.line(CX[i] - hw, 364, CX[i] + hw, 364).stroke({ color: C_INK, width: 1.8 });
    figText(gg, '2', CX[i], 396, FS, {});
