}

/* ---------------- numeric readout (HTML panel) ---------------- */
function figReadout() {
  var el = document.getElementById('readout');
  if (!el) return;
  if (!figState.showReadout) { el.style.display = 'none'; return; }
  el.style.display = '';
  var x = figState.x, c = Math.cos(x), sn = Math.sin(x), tn = Math.tan(x);
  el.innerHTML =
    'x = ' + fmt(x, 2) + ' rad = ' + fmt(x * 180 / Math.PI, 1) + '\u00b0<br>' +
    'tan x/2 = ' + fmt(tn / 2) + ' \u2265 x/2 = ' + fmt(x / 2) + '<br>' +
    '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u2265 sin x/2 = ' + fmt(sn / 2) + '<br>' +
    '<b>cos x = ' + fmt(c, 4) + '<br>&nbsp;&nbsp;\u2264 sin x / x = ' + fmt(sn / x, 4) +
    '<br>&nbsp;&nbsp;\u2264 1/cos x = ' + fmt(1 / c, 4) + '</b>';
}

